import java.util.*;
import java.io.*;

public class Main {
    static int[] scheduleMeetings(int rooms, long[] start, long[] end) {
        // Write your solution here
        int[] res = new int[start.length];
        Arrays.fill(res, -1);
        return res;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int m = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        long[] start = new long[q], end = new long[q];
        for (int i = 0; i < q; i++) {
            in.nextToken();
            start[i] = (long) in.nval;
            in.nextToken();
            end[i] = (long) in.nval;
        }
        int[] res = scheduleMeetings(m, start, end);
        StringBuilder sb = new StringBuilder();
        for (int x : res) sb.append(x).append('\n');
        System.out.print(sb);
    }
}
